    abortControllerRef.current = controller

    try {
      const res = await fetch('/api/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        signal: controller.signal,
        body: JSON.stringify({
          action: 'intent',
          items: itemsToPurchase,
          deliveryMode: activeDeliveryMode,
          shippingAddress: isPhysical && activeDeliveryMode === 'delivery' ? address.trim() : null,
        }),
      })

      const data = await res.json()
      if (!res.ok || !data.success) {
        throw new Error(data.error || 'Error al preparar la pasarela de pago')
      }

      setClientSecret(data.clientSecret)
      setActivePaymentIntentId(data.paymentIntentId)
      setStep('payment')
    } catch (err: unknown) {
      if ((err as Error).name === 'AbortError') return
      const msg = err instanceof Error ? err.message : 'Error al conectar con la pasarela'
      setErrorMessage(msg)
    } finally {
      setLoadingIntent(false)
    }
  }

