export type StoreConfirmPaymentInput = z.infer<typeof storeConfirmPaymentSchema>

export interface CheckoutResultSuccess {
  success: true
  data: {
    orderId: string
    total: number
    subtotal: number
    shippingFee: number
  }
}

export interface CheckoutResultError {
  success: false
  code: 'INVALID_INPUT' | 'PROFILE_NOT_FOUND' | 'PRODUCTS_NOT_FOUND' | 'INACTIVE_PRODUCTS' | 'ADDRESS_REQUIRED' | 'INSUFFICIENT_STOCK' | 'TRANSACTION_FAILED' | 'PAYMENT_UNCONFIRMED'
  error: string
  details?: unknown
}

export type CheckoutResult = CheckoutResultSuccess | CheckoutResultError

/**
 * Fase 2: Confirma el pago verificado en Stripe y ejecuta atómicamente la orden
 * en PostgreSQL. Si el stock se agotó en el segundo del cobro, emite reembolso automático.
 */
export async function confirmStorePayment(
  profileId: string,
  rawInput: unknown
): Promise<CheckoutResult> {
  const parsed = storeConfirmPaymentSchema.safeParse(rawInput)
  if (!parsed.success) {
    const firstIssue = parsed.error.issues[0]
    return {
      success: false,
      code: 'INVALID_INPUT',
      error: firstIssue?.message || 'Datos de confirmación inválidos',
      details: parsed.error.issues,
    }
  }

  const { paymentIntentId, items, deliveryMode, shippingAddress } = parsed.data

  // 1. Verificar el pago con Stripe SDK
  let stripe
  try {
    stripe = getStripeClient()
    const paymentIntent = await stripe.paymentIntents.retrieve(paymentIntentId)

    if (paymentIntent.status !== 'succeeded') {
      return {
        success: false,
        code: 'PAYMENT_UNCONFIRMED',
        error: `El estado del pago es '${paymentIntent.status}'. No se ha completado la transacción.`,
      }
    }
  } catch (stripeErr: unknown) {
    const msg = stripeErr instanceof Error ? stripeErr.message : String(stripeErr)
    console.error('[checkout.service] Error al verificar PaymentIntent en Stripe:', msg)
    return {
      success: false,
      code: 'TRANSACTION_FAILED',
      error: 'Error al validar el pago con la entidad bancaria.',
    }
  }

  // 2. Evaluar el carrito y precios
  const evaluation = await evaluateStoreCart(profileId, items, deliveryMode, shippingAddress)
  if (!evaluation.success) {
    return evaluation
  }

  const admin = createAdminClient()

  // 3. Ejecutar la RPC atómica en PostgreSQL
  const { data: orderId, error: rpcError } = await admin.rpc('create_store_order_transaction', {
    p_owner_id: profileId,
    p_payment_method: 'credit_card',
    p_shipping_address: evaluation.hasPhysicalProducts && deliveryMode === 'delivery' ? evaluation.finalAddress : null,
    p_total_amount: evaluation.totalAmount,
    p_items: evaluation.orderItemsData,
  })

  if (rpcError || !orderId) {
    const errMsg = rpcError?.message || ''
    console.error('[checkout.service] Error en create_store_order_transaction tras cobro exitoso:', errMsg)

    // Rollback automático: Reembolsar a la tarjeta si el stock se agotó durante el pago
    if (errMsg.toLowerCase().includes('stock insuficiente')) {
      try {
        await stripe.refunds.create({
          payment_intent: paymentIntentId,
        })
        console.warn(`[checkout.service] Reembolso automático emitido exitosamente para PaymentIntent ${paymentIntentId}`)
      } catch (refundErr: unknown) {
        console.error('[checkout.service] Error crítico al emitir reembolso automático:', refundErr)
      }

      return {
        success: false,
        code: 'INSUFFICIENT_STOCK',
        error: `${errMsg}. El importe ha sido reembolsado automáticamente a tu tarjeta.`,
      }
    }

    return {
      success: false,
      code: 'TRANSACTION_FAILED',
      error: 'Error al registrar el pedido en el sistema.',
    }
  }

  // Sincronizar orderId en los metadatos de Stripe para reconciliación en webhooks
  try {
    if (stripe && typeof stripe.paymentIntents?.update === 'function') {
      await stripe.paymentIntents.update(paymentIntentId, {
        metadata: { order_id: orderId },
      })
    }
  } catch (metaErr) {
    console.warn('[checkout.service] No se pudo adjuntar order_id a PaymentIntent en Stripe:', metaErr)
  }

  return {
    success: true,
    data: {
      orderId,
      total: evaluation.totalAmount,
      subtotal: evaluation.subtotal,
      shippingFee: evaluation.shippingFee,
    },
  }
}

