          const totalAmount = (objectData.amount_total || objectData.amount || 0) / 100
          const targetVetId = existingAppt?.vet_id || (payload?.metadata?.vet_id as string | undefined) || null
          if (targetVetId) {
            const { data: newInv, error: newInvErr } = await admin.from('invoices').insert({
              appointment_id: appointmentId,
              vet_id: targetVetId,
              status: 'paid',
              total: totalAmount,
              subtotal: totalAmount,
              tax_amount: 0
            }).select('id').maybeSingle()
            if (newInvErr) {
              console.error('[webhooks/payments] Error al crear factura de respaldo:', newInvErr.message)
            }
            inv = newInv
          } else {
            console.error('[webhooks/payments] No se puede crear factura de respaldo: vet_id no disponible para cita', appointmentId)
          }
        }

        if (inv && paymentIntentId) {
          // 3. Registrar o actualizar el pago
          const { error: payErr } = await admin.from('payments').upsert({
            invoice_id: inv.id,
            amount: (objectData.amount_total || objectData.amount || 0) / 100,
            payment_method: 'credit_card',
            gateway_reference_id: String(paymentIntentId),
            idempotency_key: toDeterministicUuid(`stripe_${paymentIntentId}`),
            status: 'completed'
          }, { onConflict: 'idempotency_key' })

          if (payErr) {
            console.error('[webhooks/payments] Error al registrar pago en BD:', payErr.message)
            return NextResponse.json({ error: 'Error al registrar pago en BD' }, { status: 500 })
          }
        }

        // 4. Notificar al veterinario solo en la primera confirmación (idempotente)
        if (!wasAlreadyConfirmed && existingAppt?.vet_id) {
          try {
            await insertNotification(admin, {
              recipient_id: existingAppt.vet_id,
              sender_id: existingAppt.owner_id,
              type: 'appointment_confirmed',
              title: 'Nueva cita confirmada',
              body: 'Un tutor ha completado el pago y confirmado su cita.',
              action_url: `/vet/appointments/${appointmentId}`,
              metadata: { appointment_id: appointmentId },
            })
          } catch {
            // Ignorar fallo de notificación para no bloquear el retorno 200 de Stripe
          }
        }
      }

export async function generateInvoiceFromAppointment(appointmentId: string) {
  const result = await svcGenerateInvoice(appointmentId)
  if (result.success) {
    revalidatePath('/vet/facturacion')
  }
  return result
}

export async function processCheckout(data: CheckoutInput | unknown) {
  const result = await svcProcessCheckout(data)
  if (result.success) {
    revalidatePath('/owner/appointments')
  }
  return result
}

export async function getBookingPaymentIntentAction(appointmentId: string) {
  return svcCreateBookingPaymentIntent(appointmentId)
}
